import { describe, expect, it } from "vitest";
import layout from "./layout/types.json";
import {
  ALL_STRUCTS, ConnectRequest, CreateAccessPointPrivateRequest, HEADER_SIZE, LdnHeader, MAGIC, NetworkInfo,
  PacketId, ProxyDataHeader, ScanFilterFull, packet, parsePacket,
} from "../src/core/codec/types.ts";
import type { Struct } from "../src/core/codec/struct.ts";

// types.json is generated by compiling test/layout/dump.cpp against the
// sysmodule's types.hpp (tools/dump-layout.sh): the compiler's own sizeof/offsetof.
const cpp = layout as Record<string, Record<string, number>>;

describe("layout matches types.hpp", () => {
  it("covers every struct in the dump", () => {
    expect(ALL_STRUCTS.map((s) => s.name).sort()).toEqual(Object.keys(cpp).sort());
  });

  for (const s of ALL_STRUCTS) {
    it(`${s.name}: size and every field offset`, () => {
      const { $size, ...offsets } = cpp[s.name];
      expect(s.size).toBe($size);
      expect(s.offsets).toEqual(offsets);
    });
  }

  it("headline sizes from the plan", () => {
    expect(NetworkInfo.size).toBe(0x480);
    expect(ConnectRequest.size).toBe(0x500);
    expect(ProxyDataHeader.size).toBe(0x14);
    expect(CreateAccessPointPrivateRequest.size).toBe(0x13c);
    expect(ScanFilterFull.size).toBe(0x60);
    expect(LdnHeader.size).toBe(HEADER_SIZE);
  });
});

// Deterministic pseudo-random bytes: every byte of the struct gets a value,
// so a round trip catches overlapping or skipped fields.
function noise(n: number, seed: number): Uint8Array {
  const out = new Uint8Array(n);
  let x = seed >>> 0 || 1;
  for (let i = 0; i < n; i++) {
    x ^= x << 13; x ^= x >>> 17; x ^= x << 5;
    out[i] = x & 0xff;
  }
  return out;
}

describe("round trips", () => {
  for (const [i, s] of ALL_STRUCTS.entries()) {
    it(`${s.name}: bytes -> object -> bytes is identity`, () => {
      const raw = noise(s.size, i + 1);
      const enc = (s as Struct<unknown>).encode(s.decode(raw));
      expect(enc).toEqual(raw);
    });
    it(`${s.name}: zero() encodes to all zeros`, () => {
      expect((s as Struct<unknown>).encode(s.zero())).toEqual(new Uint8Array(s.size));
    });
  }

  it("decodes known values at the right places", () => {
    const info = NetworkInfo.zero();
    info.network_id.intent_id.local_communication_id = 0x01000bb9000e0000n;
    info.network_id.intent_id.scene_id = 0x1234;
    info.ldn.node_count_max = 8;
    info.ldn.nodes[7].ipv4_address = 0x0a720003;
    info.ldn.nodes[7].user_name.set(new TextEncoder().encode("Host"));
    info.ldn.authentication_id = 0xffffffffffffffffn;
    const b = NetworkInfo.encode(info);
    const dv = new DataView(b.buffer);
    expect(dv.getBigInt64(0, true)).toBe(0x01000bb9000e0000n);
    expect(dv.getUint16(10, true)).toBe(0x1234);
    expect(b[0x50 + 22]).toBe(8);
    const node7 = 0x50 + 24 + 7 * 64;
    expect(dv.getUint32(node7, true)).toBe(0x0a720003);
    expect(new TextDecoder().decode(b.subarray(node7 + 12, node7 + 16))).toBe("Host");
    expect(dv.getBigUint64(0x478, true)).toBe(0xffffffffffffffffn);
    expect(NetworkInfo.decode(b)).toEqual(info);
  });

  it("signed fields keep their sign", () => {
    const h = ProxyDataHeader.zero();
    h.info.protocol = -1;
    expect(ProxyDataHeader.decode(ProxyDataHeader.encode(h)).info.protocol).toBe(-1);
  });
});

describe("framing", () => {
  it("packet() writes the 12-byte header", () => {
    const p = packet(PacketId.Ping, new Uint8Array([0, 7]));
    expect(Array.from(p)).toEqual([0x52, 0x4c, 0x44, 0x4e, 254, 1, 0, 0, 2, 0, 0, 0, 0, 7]);
    expect(new DataView(p.buffer).getUint32(0, true)).toBe(MAGIC);
  });

  it("parsePacket accepts exactly one packet", () => {
    const p = packet(PacketId.Scan, new Uint8Array(0x60));
    expect(parsePacket(p)).toMatchObject({ type: PacketId.Scan });
    expect(parsePacket(p)!.payload.length).toBe(0x60);
  });

  it("parsePacket rejects bad magic, version, size and truncation", () => {
    const good = packet(PacketId.Ping, new Uint8Array(2));
    const bad = (f: (b: Uint8Array) => void) => {
      const b = good.slice();
      f(b);
      return parsePacket(b);
    };
    expect(bad((b) => (b[0] = 0))).toBeNull();
    expect(bad((b) => (b[5] = 2))).toBeNull();
    expect(bad((b) => (b[8] = 3))).toBeNull();
    expect(bad((b) => (b[11] = 0x80))).toBeNull(); // negative size
    expect(parsePacket(good.subarray(0, 13))).toBeNull();
    expect(parsePacket(good.subarray(0, 8))).toBeNull();
    expect(parsePacket(packet(PacketId.ProxyData, new Uint8Array(131072 - 12)))).toBeNull();
    expect(parsePacket(packet(PacketId.ProxyData, new Uint8Array(131072 - 13)))).not.toBeNull();
  });
});
